<?php
declare(strict_types=1);
require __DIR__.'/../inc/db.php';require __DIR__.'/../inc/page.php';require_staff_or_admin();$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_post_csrf();try{$id=(int)($_POST['addon_id']??0);$change=(int)($_POST['quantity_change']??0);$reason=trim((string)($_POST['reason']??''));if(!$id||$change===0||mb_strlen($reason)<3)throw new RuntimeException('Choose an add-on, enter a non-zero correction, and provide a reason.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT quantity FROM addons WHERE id=? AND is_active=1 FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if($old===false)throw new RuntimeException('Add-on not found.');$new=(int)$old+$change;if($new<0)throw new RuntimeException('Stock cannot be reduced below zero.');$pdo->prepare('UPDATE addons SET quantity=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO addon_inventory_adjustments(addon_id,quantity_change,resulting_stock,reason,actor_user_id) VALUES(?,?,?,?,?)')->execute([$id,$change,$new,$reason,user_id()]);$pdo->commit();redirect('addons.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$message=$e->getMessage();}}
$addons=$pdo->query('SELECT id,name,quantity FROM addons WHERE is_active=1 ORDER BY name')->fetchAll();$history=$pdo->query('SELECT a.*,d.name addon_name,u.name actor_name FROM addon_inventory_adjustments a JOIN addons d ON d.id=a.addon_id LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.created_at DESC LIMIT 200')->fetchAll();page_start('Add-on inventory');
?><main class="container py-4"><h1 class="h3">Add-on inventory</h1><p class="help-text">History is append-only. Enter a positive or negative correction with a reason.</p><?php if($message):?><div class="alert alert-danger"><?=e($message)?></div><?php endif;?><form method="post" class="app-card p-4 row g-3"><?=csrf_field()?><div class="col-md-4"><label class="form-label">Add-on</label><select name="addon_id" class="form-select" required><option value="">Choose</option><?php foreach($addons as $a):?><option value="<?=(int)$a['id']?>"><?=e($a['name'])?> (<?=(int)$a['quantity']?>)</option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Stock correction</label><input type="number" name="quantity_change" class="form-control" placeholder="Example: 10 or -2" required></div><div class="col-md-5"><label class="form-label">Reason</label><input name="reason" maxlength="255" class="form-control" required></div><div><button class="btn btn-purple">Record correction</button></div></form><div class="table-responsive app-card mt-4"><table class="table mb-0"><thead><tr><th>Add-on</th><th>Change</th><th>Result</th><th>Reason</th><th>Actor</th><th>Date</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['addon_name'])?></td><td><?=(int)$h['quantity_change']>0?'+':''?><?=(int)$h['quantity_change']?></td><td><?=(int)$h['resulting_stock']?></td><td><?=e($h['reason'])?></td><td><?=e($h['actor_name']??'System')?></td><td><?=e($h['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></main><?php page_end();
